var html = document.documentElement;
var themeSelector = document.getElementById("theme-selector");
var storedTheme = localStorage.getItem("theme");
var name = document.querySelector("#name");
var slug = document.querySelector("#slug");
var title = document.querySelector("#title");

// Refactored theme handling logic
var applyTheme = function applyTheme(theme) {
  html.setAttribute("data-theme", theme);
  localStorage.setItem("theme", theme);
};
if (storedTheme) {
  applyTheme(storedTheme);
  if (themeSelector) themeSelector.value = storedTheme;
} else if (themeSelector) {
  var defaultTheme = themeSelector.value;
  applyTheme(defaultTheme);
}
html.removeAttribute("hidden");
if (themeSelector) {
  themeSelector.addEventListener("change", function (event) {
    applyTheme(event.target.value);
  });
}
if (name) {
  name.addEventListener("change", function () {
    fetch("/dashboard/categories/checkSlug?name=" + name.value).then(function (response) {
      return response.json();
    }).then(function (data) {
      return slug.value = data.slug;
    });
  });
}
if (title) {
  title.addEventListener("change", function () {
    fetch("/dashboard/posts/checkSlug?title=" + title.value).then(function (response) {
      return response.json();
    }).then(function (data) {
      return slug.value = data.slug;
    });
  });
}
document.addEventListener("trix-file-accept", function (e) {
  e.preventDefault();
});
function priviewImage() {
  var image = document.querySelector("#image");
  var imgPriview = document.querySelector(".img-priview");
  imgPriview.style.display = "block";
  var oFReader = new FileReader();
  oFReader.readAsDataURL(image.files[0]);
  oFReader.onload = function (oFREvent) {
    imgPriview.src = oFREvent.target.result;
  };
}

